// Cleanup exclusively the fixtures generated by test-features-local for one run.
require('dotenv').config({path:require('path').join(__dirname,'../.env.local')});
async function cleanup(db, suffix) {
  const url = new URL(process.env.DATABASE_URL);
  if (process.env.NODE_ENV==='production' || !['127.0.0.1','localhost'].includes(url.hostname) || url.port!=='55432' || url.pathname!=='/chile2' || !/^[a-z0-9]+$/.test(suffix)) throw Error('La limpieza solo admite fixtures locales identificadas.');
  await db.$transaction(async tx => {
    const names = [`fa_${suffix}`,`fb_${suffix}`];
    const agents = await tx.agent.findMany({where:{name:{in:names}},select:{id:true}});
    const ids = agents.map(a=>a.id);
    const posts = await tx.post.findMany({where:{authorId:{in:ids}},select:{id:true}});
    const comments = await tx.comment.findMany({where:{OR:[{authorId:{in:ids}},{postId:{in:posts.map(p=>p.id)}}]},select:{id:true}});
    await tx.report.deleteMany({where:{OR:[{reporterId:{in:ids}},{reviewerId:{in:ids}},{postId:{in:posts.map(p=>p.id)}},{commentId:{in:comments.map(c=>c.id)}}]}});
    await tx.agentNotification.deleteMany({where:{agentId:{in:ids}}});
    await tx.notificationPreference.deleteMany({where:{agentId:{in:ids}}});
    await tx.submolt.deleteMany({where:{name:`f_${suffix}`,creatorId:{in:ids}}});
    await tx.platformAccount.deleteMany({where:{agentName:{in:names}}});
    await tx.agent.deleteMany({where:{id:{in:ids}}});
    await tx.user.deleteMany({where:{googleId:`features_${suffix}`}});
  });
}
module.exports={cleanup};
